import{a as n}from"./chunk-2RJSKV3I.js";import{a as e}from"./chunk-SH4CHYBR.js";import"./chunk-U37H3HIF.js";var t=n(e,["Optional. Nur f\xFCr die W\xF6rter auf dem Bildschirm, die Namen der Dateien, die Sie daf\xFCr erstellen, und den Link in der Seitenleiste. Nichts ist damit verbunden.","Assistenten und ihre Links…","Neben Grading Studio \xF6ffnen","Der Browser hat das \xD6ffnen verhindert. Erlauben Sie Pop-ups f\xFCr diese Seite und versuchen Sie es dann erneut.","Ihr Assistent","Ein Link beginnt mit https://","Name","Mein Assistent","Keiner, oder keine Angabe","Kein Assistent angegeben.","Ihr Assistent ist jetzt {name}.","{name} jetzt \xF6ffnen","Ein Klick auf den Namen \xF6ffnet ihn","Ein anderer…","Weitere, die Sie nutzen","Ein Klick auf den Namen Ihres Assistenten in der Seitenleiste zeigt diese ebenfalls. W\xE4hlen Sie dort einen aus: Er \xF6ffnet sich und wird der verwendete Assistent, mit seinem eigenen Link.","In einem Fenster rechts","Nebeneinander: Er ist auf jedem Bildschirm in der Seitenleiste. Klicken Sie in Chrome dort mit der rechten Maustaste darauf und w\xE4hlen Sie Link in geteilter Ansicht \xF6ffnen, um beides in einem Fenster zu haben. Grading Studio sendet ihm nichts; er sieht nur, was Sie einf\xFCgen oder anh\xE4ngen.","Ihren Assistenten \xE4ndern","Link Ihres Assistenten \xE4ndern","Assistenten \xE4ndern, zu denen Sie wechseln","\xC4ndern, wo sich Ihr Assistent \xF6ffnet","In einem neuen Tab","\xD6ffnet sich auf","Leer f\xFCr die \xFCbliche Seite. Ein eigener Link kann zu Ihrem Schulkonto, einem Projekt oder Ihrem eigenen gespeicherten Helfer f\xFChren.","Ihr KI-Assistent","Wie die Dateien, die Sie zur\xFCckgeben, zun\xE4chst eingestellt sind. Das Feld Zur\xFCckgeben kann das f\xFCr eine Aufgabe \xE4ndern.","Namen auf Vergleichsarbeiten verdecken","Zur\xFCckgeben","Jede Datei nach Lernendem und Aufgabe benennen","Ein PDF pro Person","83 %","83,3 %","83,33 %","Wie ein Klassendurchschnitt oder eine Zeitraumnote im Tab Noten und im Notenbuch angezeigt wird. Bei der Berechnung wird nichts gerundet.","Nachkommastellen im Schnitt","Blendet die Leisten des Browsers aus. F macht dasselbe von \xFCberall au\xDFer aus einem Textfeld, und Esc beendet es.","Vollbild","Vollbild","Vollbild verlassen","Ihre eigene Liste: eine F\xE4higkeit, ein Standard, alles, wonach Sie Bewertungen sehen m\xF6chten.","Ein neues Lernziel, in Ihren Worten","Anf\xFCgen","{name} entfernt.","Lernziele","Lernziel {n}","Optional. Ein Lernziel ist alles, wonach Sie Bewertungen sehen m\xF6chten: eine F\xE4higkeit wie „Nutzt Belege“ oder ein Standard Ihrer Schule. Versehen Sie Rasterkriterien und Quizfragen mit einem Lernziel, und jede Klasse bekommt einen Tab Lernziele.","Entfernen","Lernziel hinzuf\xFCgen","Lernziel verschieben","Lernziel umbenennen","Lernziel entfernen","Ordnen Sie Rasterkriterien unter Raster einrichten und Quizfragen unter Quizfelder zu. Ein entferntes Lernziel verschwindet \xFCberall, wo es zugeordnet war; keine Bewertung \xE4ndert sich.","Dieses Lernziel steht schon auf der Liste.","Nach oben","Meine Einrichtung","Ein eigener Ordner auf diesem Computer, in dem {name} Ihre Stunden, Einheiten, Aktivit\xE4ten, Bewertungsraster und Ihren Stundenplan lesen und \xE4ndern kann. Dort gespeicherte Entw\xFCrfe erscheinen auf Ihren Kursverl\xE4ufen, als nicht gepr\xFCft markiert. Bewertungsdaten kommen nie hinein.","Aus Ihrem Planer-Ordner eingetroffen, nicht gepr\xFCft.","Dieser Browser braucht erneut Ihre Erlaubnis f\xFCr","Zur\xFCck zu Ihrer Fassung","Zur\xFCck zu Ihrer Fassung. Die von {name} finden Sie unter Versionen.","{a} neu, {c} aktualisiert aus dem Planer-Ordner","{n} aktualisiert aus dem Planer-Ordner","{n} neu aus dem Planer-Ordner","Ordner \xE4ndern","Von {name} in Ihrem Planer-Ordner ge\xE4ndert, nicht gepr\xFCft. Ihre Fassung finden Sie unter Versionen.","Dieser Ordner konnte nicht verwendet werden","In diesem Ordner liegen Bewertungsdateien von Grading Studio. W\xE4hlen oder erstellen Sie einen Ordner nur f\xFCr die Planung, etwa „Stunden“.","Planer-Ordner","Planer-Ordner verkn\xFCpfen","Planer-Ordner verkn\xFCpft: {name}","Verkn\xFCpft:","Im Planer-Ordner nachsehen","Dieser Browser kann keinen Ordner verkn\xFCpfen. Chrome oder Edge auf einem Computer k\xF6nnen das.","Kein Ordner verkn\xFCpft.","Keine \xC4nderungen im Planer-Ordner","Erneut erlauben","Der Planer-Ordner konnte nicht gelesen werden","Lesen Sie es durch und markieren Sie es dann als gepr\xFCft.","Als gepr\xFCft markieren","Dies ist das Beispiel, daher ist das Verkn\xFCpfen eines Ordners hier ausgeschaltet. Verlassen Sie das Beispiel, um es mit Ihren eigenen Stunden zu nutzen.","Fassung von {name} (Sie sind zu Ihrer zur\xFCckgekehrt)","QR-Code f\xFCr Grading Studio","Richten Sie die Kamera Ihres Handys auf den Code und tippen Sie auf den Link, oder geben Sie die Adresse oben ein.","Auf dem iPhone: Tippen Sie in Safari auf Teilen und dann auf Zum Home-Bildschirm.","Auf Android: Tippen Sie in Chrome auf das Men\xFC ⋮ und dann auf Zum Startbildschirm hinzuf\xFCgen oder App installieren.","\xD6ffnen Sie Grading Studio vom Home-Bildschirm und tippen Sie auf Mit Google anmelden. Verwenden Sie dasselbe Google-Konto wie auf diesem Computer.","Ihre Klassen, Punkte und Aufgaben bleiben dann auf beiden gleich. Auf dem Handy k\xF6nnen Sie Punkte eintragen und Arbeiten ansehen; korrigiert wird am Computer.","Wenn Google meldet, dass die App nicht \xFCberpr\xFCft wurde, tippen Sie auf Erweitert und dann auf Weiter zu Grading Studio. Der Anmeldeschl\xFCssel wurde f\xFCr Ihre Kopie erstellt und nicht von Google gepr\xFCft, und die App kann nur ihren eigenen versteckten Ordner in Ihrem Drive nutzen.","Auf dem Handy nutzen","Auf einem Telefon gr\xF6\xDFere Schaltfl\xE4chen und Tabs am unteren Rand. Arbeiten bleiben auf dem Computer; Bewertungen, Anwesenheit, Pl\xE4ne und Aufgaben funktionieren hier.","Telefonansicht","Gilt ab dem n\xE4chsten \xD6ffnen der Seite auf einem Telefon","Telefonansicht auf einem Telefon verwenden","Telefonversion \xF6ffnen","Um sie hier zu sehen, \xF6ffnen Sie ein schmales Fenster dieser App. Es enth\xE4lt dieselbe Arbeit.","Zum Beispiel IB MYP. Eine neue Klasse einer MYP-Lehrkraft beginnt mit MYP-Kriterien. Lassen Sie das Feld leer, wenn es nicht zutrifft.","Programm: {name}.","Programm","Das Programm, das Sie unterrichten","Kein Programm angegeben.","Ihr Programm \xE4ndern","Ihre Arbeit hier wartet mit dem Synchronisieren, bis Sie das tun.","Erneut anmelden","Google m\xF6chte, dass Sie sich erneut anmelden","Melden Sie sich mit demselben Google-Konto wie auf Ihrem Computer an. Ihre Klassen, Punkte, Pl\xE4ne und Aufgaben kommen dann hierher.","Mit Google anmelden","Holen Sie Ihre Arbeit vom Computer","Nichts erreicht einen KI-Assistenten, au\xDFer Sie geben ihm selbst eine Datei. Arbeiten, Namen, Bewertungen und Bemerkungen bleiben in diesem Browser und in Ihrem eigenen verkn\xFCpften Ordner.","Mit Assistent teilen, in der Einrichtung einer Aufgabe, erstellt eine Datei, die Sie ihm geben: die Arbeiten mit verdeckten Namen oder nur Ihre Markierungen. Alle Lernenden werden zu einem zuf\xE4lligen Code, und der Schl\xFCssel zu den Codes bleibt in diesem Browser.","Der Planer-Ordner enth\xE4lt nur Stunden. Wenn Sie Ihren Assistenten in einem Ordner auf Ihrem Computer arbeiten lassen, nehmen Sie diesen: Bewertungsdaten kommen nie hinein, und der Planer lehnt einen Ordner mit Bewertungsdateien ab.","Meine Einrichtung, unter Klassen, kann Ihrem Assistenten einen Prompt geben, damit er Ihre Einrichtung f\xFCr Sie schreibt. Darin steht nie etwas \xFCber Lernende.","Was Ihr Assistent sehen kann und was nicht","Datenschutz, in der Hilfe","Macht die W\xF6rter der App auf diesem Computer gr\xF6\xDFer oder kleiner. Die Arbeit, die Sie korrigieren, beh\xE4lt ihren eigenen Zoom.","Textgr\xF6\xDFe der App","Gro\xDF","Normal","Klein","Sehr gro\xDF","Wie Sie arbeiten, als ein Textblock: Ihre Klassen und wann sie stattfinden, der Kalender, Zeitr\xE4ume, Ihre Bewertung, gespeicherte Bewertungsraster und Bemerkungen. Nie etwas \xFCber Lernende. \xDCbernehmen Sie einen von Ihrem Assistenten oder einer Kollegin, oder kopieren Sie Ihren f\xFCr einen anderen Computer.","Auf Folie 2 wird eine Agenda eingef\xFCgt","Ihr KI-Assistent ist {name}","Kein KI-Assistent angegeben","Nicht in der Assistentenliste der Seitenleiste: {list}","Alle Assistenten, die die App kennt, stehen in der Liste der Seitenleiste","Ihr Assistent \xF6ffnet sich in einem Fenster rechts auf dem Bildschirm","Ihr Assistent \xF6ffnet sich in einem neuen Tab","Ihr Assistent \xF6ffnet sich auf {link}","Ihr Assistent \xF6ffnet sich auf seiner \xFCblichen Seite","Andere Assistenten mit eigenem Link: {list}","Kein weiterer Assistent hat einen eigenen Link","Anwesenheit in Grading Studio erfassen","Anwesenheit nicht in Grading Studio erfassen","{grade} ab {n} %","Noten: {list}",{one:"1 Teil \xFCbernehmen",other:"{n} Teile \xFCbernehmen"},"Noten bleiben bei h\xF6chstens 100 %","Pr\xFCfen",{one:"1 Bemerkung zur Auswahl beim Korrigieren: „{first}“",other:"{n} Bemerkungen zur Auswahl beim Korrigieren, etwa „{first}“"},"Meine Einrichtung kopieren","Prompt kopieren","Kurs f\xFCr {list}. Klassen im selben Kurs sind verkn\xFCpft.","Namen werden auf exportierten Vergleichsarbeiten verdeckt","Namen werden auf exportierten Vergleichsarbeiten nicht verdeckt",{one:"1 Teil der Einrichtung \xFCbernommen.",other:"{n} Teile der Einrichtung \xFCbernommen."},"Hat ein Typ noch keine Eintr\xE4ge, werden die anderen Typen verwendet","Ein Typ ohne Eintr\xE4ge z\xE4hlt als 0","Noch nichts zu lesen. F\xFCgen Sie zuerst den Einrichtungstext ein.","Das ist zu lang f\xFCr eine Einrichtung. Eine Einrichtung umfasst h\xF6chstens ein paar Seiten Text.","In diesem Text wurde keine Einrichtung gefunden. Eine Einrichtung beginnt mit { und endet mit }. Wenn Ihr Assistent sie abgeschnitten hat, bitten Sie ihn erneut um den ganzen Block.",'Dieser Text ist keine Grading-Studio-Einrichtung: Er hat keine Zeile "gradingStudioSetup". Bitten Sie Ihren Assistenten mit dem Prompt erneut um den Einrichtungsblock.',{one:"1 Termin im Kalender: {list}",other:"{n} Termine im Kalender: {list}"},"Das hat nicht geklappt, und nichts wurde ge\xE4ndert. Versuchen Sie es erneut.","Eine Pause dauert {n} Minuten",{one:"Tagesziel: 1 Minute",other:"Tagesziel: {n} Minuten"},{one:"Tagesziel: 1 Arbeit",other:"Tagesziel: {n} Arbeiten"},"Freistunden werden zum Korrigieren angeboten","Freistunden werden nicht zum Korrigieren angeboten",{one:"Die Zeit wird nach 1 Minute ohne Aktivit\xE4t nicht mehr gez\xE4hlt",other:"Die Zeit wird nach {n} Minuten ohne Aktivit\xE4t nicht mehr gez\xE4hlt"},"Eine Fokus-Sitzung dauert {n} Minuten","Eine Stunden-Sitzung dauert {n} Minuten","Stimmung, Lautst\xE4rke und Hintergrundklang der Musik","Lo-fi-Musik, w\xE4hrend eine Sitzung l\xE4uft","Keine Musik w\xE4hrend einer Sitzung","Kein Tagesziel","Planung au\xDFerhalb von Fokus-Sitzungen z\xE4hlt nach {n} Minuten durchgehender Arbeit","Planung z\xE4hlt nur in Fokus-Sitzungen","Z\xE4hler sind w\xE4hrend einer Fokus-Sitzung ausgeblendet","Z\xE4hler bleiben w\xE4hrend einer Fokus-Sitzung sichtbar","F\xFCr jede Sitzung wird ein Ziel vorgeschlagen","F\xFCr Sitzungen wird kein Ziel vorgeschlagen","K\xFCrzeste Arbeiten zuerst in einer Fokus-Sitzung","Arbeiten in ihrer \xFCblichen Reihenfolge in einer Fokus-Sitzung","Ein leiser Ton, wenn eine Sitzung oder eine Pause endet","Kein Ton, wenn eine Sitzung endet","Die verbleibende Zeit steht im Namen des Browser-Tabs","Die verbleibende Zeit steht nicht im Namen des Browser-Tabs","Bewertungs- und Planungszeit werden gez\xE4hlt","Bewertungs- und Planungszeit werden nicht gez\xE4hlt","Ein Wochenr\xFCckblick am {day}",{one:"Wochenziel: 1 Minute",other:"Wochenziel: {n} Minuten"},"Kein Wochenr\xFCckblick",{one:"Wochenziel: 1 Arbeit",other:"Wochenziel: {n} Arbeiten"},"Getippte Namen werden f\xFCr Sie gefunden und verdeckt","Sie verdecken Namen selbst","Im Vollbild sind die Liste der Lernenden und die Werkzeuge ausgeblendet, bis Sie darauf zeigen","Im Vollbild ist die Liste der Lernenden ausgeblendet, bis Sie darauf zeigen","Im Vollbild bleiben die Liste der Lernenden und die Werkzeuge neben der Arbeit",{one:"1 Lernziel: {list}",other:"{n} Lernziele: {list}"},"Meine Einrichtung","Anwesenheit","Woraus eine Note besteht","Halbjahr und freie Tage","Klassen und Stundenplan","Gespeicherte Kommentare","Stundenfolien","Fokus-Timer und Tagesziel","Lernziele","Ihre Bewertung","Korrigieren und Zur\xFCckgeben","Breite der Seitenleiste","Gespeicherte Bewertungsraster","Ihre Schule","Klassen-Tabs","Zeitr\xE4ume","Aufgaben","IB-Programm, Kriterien und Notengrenzen f\xFCr {list}","schwarz","blau","gr\xFCn","lila","rot",{one:"Im Text stand etwas \xFCber Lernende. Es wurde weggelassen: Lernende kommen nur auf der Seite ihrer Klasse hinzu.",other:"Im Text standen {n} Angaben \xFCber Lernende. Sie wurden weggelassen: Lernende kommen nur auf der Seite ihrer Klasse hinzu."},"Ein Link zum Schulsystem f\xFCr {list}","{list} und {n} weitere","Die Liste der Lernenden zeigt Prozente","Die Liste der Lernenden zeigt Punkte von der Gesamtzahl","E-Mail-Schaltfl\xE4chen \xF6ffnen die Mail-App des Computers","E-Mail-Schaltfl\xE4chen \xF6ffnen eine neue Nachricht in Gmail","E-Mail-Schaltfl\xE4chen \xF6ffnen eine neue Nachricht in Outlook im Web",{one:"Eine neue Klasse: {list}",other:"{n} neue Klassen: {list}"},"Folie hinzuf\xFCgen f\xFCgt eine Folie vom Typ {name} ein","Auf Folie 2 wird keine Agenda eingef\xFCgt","Eine Note kann \xFCber 100 % liegen","Ein Teil wurde f\xFCr eine neuere Version oder auf eine Weise geschrieben, die diese Version nicht kennt, daher bleibt er unver\xE4ndert.",{one:"1 freier Tag: {list}",other:"{n} freie Tage: {list}"},"Die Eingabeliste ist nach Vornamen sortiert","Die Eingabeliste ist nach Nachnamen sortiert","Die Eingabeliste folgt der Liste","Die gleiche Art Text, aus dem, was hier ist, f\xFCr einen anderen Computer oder eine Kollegin. Er enth\xE4lt nie eine Liste, eine Bewertung oder eine Arbeit.","Ihre Einrichtung","Der Einrichtungstext","Personen auf der Seite Schule: {list}","Was sich \xE4ndern w\xFCrde","Programm: {name}","Punkte sind nach Erfolg gef\xE4rbt: voll, teilweise oder keine","Punkte werden in {ink} geschrieben","Punkte werden in der Farbe des Stifts geschrieben","Pl\xE4tze f\xFCr Personen auf der Seite Schule: {list}","Rasterkriterien: {list}","Bei einer Wiederholung z\xE4hlt der Schnitt der Versuche","Bei einer Wiederholung z\xE4hlt die h\xF6chste Bewertung","Bei einer Wiederholung z\xE4hlt die letzte Bewertung",{one:"{name} (1 Kriterium)",other:"{name} ({n} Kriterien)"},{one:"Ein neues Bewertungsraster: {list}",other:"{n} neue Bewertungsraster: {list}"},"Neue Formulierungen f\xFCr {list}, die Sie schon haben","Bereits gespeicherte Tage bleiben erhalten.","F\xFCr alle Ihre Klassen. Bewertungen werden nicht ge\xE4ndert; Noten werden daraus neu berechnet.","Wird dem Kalender hinzugef\xFCgt. Bereits eingetragene freie Tage bleiben.","Vorhandene Klassen bleiben, mit ihren Lernenden und ihren Arbeiten. Dadurch werden keine Lernenden hinzugef\xFCgt.","Wird den Bemerkungen hinzugef\xFCgt, aus denen Sie beim Korrigieren w\xE4hlen.","F\xFCr jeden Foliensatz, den Sie ab jetzt erstellen.","Zum Zuordnen von Rasterkriterien und Quizfragen.","Vorhandene Aufgaben behalten ihr eigenes Raster und ihre Skala, und keine Bewertung \xE4ndert sich.","Keine Arbeit, Markierung oder Bewertung \xE4ndert sich.","Bei jeder Aufgabe unter Raster einrichten w\xE4hlbar.","Nur die W\xF6rter, die die App verwendet. Nichts ist damit verbunden.","Die anderen Seiten bleiben unter Mehr.","Eine Aufgabe z\xE4hlt zu dem Zeitraum, in den ihr Abgabedatum f\xE4llt.","Gel\xF6scht: {list}. Ihre Zeilen kommen in die Kategorie, zu der ihre W\xF6rter passen.","Hier w\xFCrde sich nichts \xE4ndern: Alles ist schon so, wie Sie es haben.","Als Datei speichern",{one:"Eine Notenskala von Punkten zu Prozent (1 Stufe)",other:"Eine Notenskala von Punkten zu Prozent ({n} Stufen)"},"Halbjahr vom {from} bis {to}","Das Notenblatt zeigt auch Noten, die auf den Arbeiten gefunden wurden","Das Notenblatt zeigt nur die in der App vergebenen Bewertungen","Folientext bleibt zwischen 28 und 36 pt","Folientext kann jede Gr\xF6\xDFe von 18 bis 44 pt haben","Kopieren Sie den Prompt und geben Sie ihn Ihrem KI-Assistenten. Er fragt Sie, was er noch nicht wei\xDF, und schreibt Ihre Einrichtung.","Kopieren Sie den Prompt und geben Sie ihn {name}. Er fragt Sie, was er noch nicht wei\xDF, und schreibt Ihre Einrichtung.","F\xFCgen Sie hier ein, was er zur\xFCckgibt, und pr\xFCfen Sie es. Nichts \xE4ndert sich, bevor Sie gesehen haben, was sich \xE4ndern w\xFCrde.","Die Lernenden geben Arbeiten \xFCber {name} ab","Kein Schulsystem angegeben","formativ","im Unterricht","summativ","Anwesenheit","Diagramme","Lernziele","Notenbuch","Fehlende Arbeiten","Andere Seite","Zeugnisbemerkungen","Sitzplan","Lernende","In der Tab-Leiste: {list}","Nur Aufgaben, Notenbuch und Lernende in der Tab-Leiste","Aufgabenkategorien: {list}","W\xF6rter, die eine Zeile zu {name} bringen: {words}","{name}: {from} – {to}","{name} wird verschoben auf {from} bis {to}","Unterrichtszeiten f\xFCr {list}, im Stundenplan","Jedes Kriterium wird mit 0 bis {n} bewertet","Jedes Kriterium wird mit 0 bis {n} bewertet, nur ganze Punkte","Bewertet mit einer Gesamtzahl von {n}","Ihre eigenen Typen: {list}","Letzte Einrichtung wiederherstellen","Wiederhergestellt wie vor der \xDCbernahme der Einrichtung.","Wiederhergestellt, au\xDFer dem, was Sie seitdem genutzt haben.","Einheitenpl\xE4ne liegen in {name}","Kein Ort f\xFCr Einheitenpl\xE4ne angegeben","Neue Einheiten in {list}","Nicht verstanden, daher unver\xE4ndert: {list}.","Eine neue Aufgabe beginnt mit {way}","IB 1 bis 7","Buchstabennoten","IB-MYP-Kriterien","Prozent","Punkte","Rasterkriterien","Eine neue Aufgabe beginnt mit {way} (jetzt {was})","Eine Zeitraumnote besteht aus {list}","Zusatzpunkte z\xE4hlen zur Arbeit im Unterricht","Zusatzpunkte z\xE4hlen zur Zeitraumnote","Zur\xFCckgegebene Dateien werden nach Lernendem und Aufgabe benannt","Zur\xFCckgegebene Dateien behalten den Namen, mit dem sie abgegeben wurden","Alle Lernenden bekommen ein PDF mit allen ihren Arbeiten","Jede Arbeit geht als eigene Datei zur\xFCck","Erneut anmelden","Jede Stunde von selbst erneuern","Google fragt jede Stunde erneut. Eingeschaltet \xF6ffnet sich kurz das kleine Google-Fenster, meist wenn Sie zur App zur\xFCckkehren. Ausgeschaltet wartet die Synchronisierung, bis Sie auf Erneut anmelden klicken.","Die Anmeldung wurde geschlossen.","Die Anmeldung wurde nicht abgeschlossen.","Melden Sie sich mit Google an, und Ihre Klassen, Bewertungen, Pl\xE4ne und Aufgaben sind auf jedem Computer und Telefon gleich, auf dem Sie sich anmelden. Nur ein versteckter eigener Ordner der App in Ihrem Drive wird verwendet, und sonst ist nichts in Ihrem Drive sichtbar.",null,"Zuletzt synchronisiert: {when}","Die Google-Anmeldung funktioniert unter der Webadresse der App, nicht in einer Kopie, die aus einer Datei ge\xF6ffnet wurde.","Google ist nicht erreichbar. Pr\xFCfen Sie die Internetverbindung.","Von Google abgemeldet","Google Drive wird nicht verwendet, solange das Beispiel ge\xF6ffnet ist.","Mit Google anmelden","Abmelden","Google: {email}","Angemeldet als {email}","wartet, bis die Seite im Vordergrund ist","Markierungen synchronisiert; Ihr Google Drive ist voll, daher bleiben die Arbeiten hier","nicht synchronisiert","Markierungen synchronisiert; Arbeiten noch nicht gesendet","offline: synchronisiert, sobald Sie wieder online sind","wird gespeichert…","Arbeiten werden gesendet…","erneut anmelden, um zu synchronisieren","synchronisiert","wird synchronisiert…","Jetzt synchronisieren","Nur f\xFCr die W\xF6rter auf dem Bildschirm. Es ist nichts damit verbunden.","Wo die Sch\xFClerinnen und Sch\xFCler ihre Arbeiten abgeben","Name","Das System meiner Schule","Auf Papier, oder keine Angabe","Woanders…","\xC4ndern, wo die Lernenden Arbeiten abgeben","F\xFCr einen Touchscreen. Maus und Trackpad funktionieren wie immer.","zeichnet, bis Sie einen Stift benutzen; danach bewegt er die Seite","zeichnet immer","Ein Finger auf der Arbeit","Tablet und Stift","bewegt immer die Seite","Die Stiftlinie wird breiter, je fester Sie dr\xFCcken","Zwei Finger bewegen immer die Seite, und Aufziehen zoomt. Solange der Stift auf der Arbeit ist, bewirkt eine aufgelegte Hand nichts.","Ihn die Einrichtung machen lassen","Haben Sie einen KI-Assistenten, der Ihren Unterricht kennt?","Weitere Klasse hinzuf\xFCgen","Noch eine Klasse","Zur\xFCck","Arbeit \xFCbernehmen","W\xE4hlen Sie Ihren Grading-Studio-Ordner oder \xFCbernehmen Sie eine Mitnahmedatei. Ihre Klassen und Arbeiten kommen mit.","Ihre Antworten konnten nicht gespeichert werden. Versuchen Sie es erneut.","Eine Klasse, zum Beispiel „Biologie 8b“","Weiter","Alles ist eingerichtet. \xD6ffnen Sie hier einige Arbeiten, oder f\xFCgen Sie in der Seitenleiste eine Klasse hinzu.","Alles ist eingerichtet. \xD6ffnen Sie hier die Arbeiten einer Klasse, oder klicken Sie in der Seitenleiste auf eine Klasse, um ihre Lernenden hinzuzuf\xFCgen.","Ordner w\xE4hlen…","Speichert im Ordner „{name}“ und in diesem Browser.","Wie bewerten Sie meistens?","Das ist nur der Ausgangspunkt f\xFCr neue Aufgaben. Jede Aufgabe kann anders bewertet werden.","Arbeiten korrigieren, Stunden planen, Arbeiten zur\xFCckgeben.","Wo geben die Lernenden ihre Arbeiten ab?","Name","Der Name des Systems Ihrer Schule","Ihre Klassen, Arbeiten, Anmerkungen und Bewertungen liegen in diesem Browser. Dieser Browser kann nicht selbst in einen Ordner speichern (Chrome oder Edge auf einem Computer k\xF6nnen es). Erstellen Sie deshalb ab und zu in den Einstellungen eine Mitnahmedatei. Die Seitenleiste erinnert Sie daran.","Wo soll Ihre Arbeit liegen?","Ihre Klassen, Arbeiten, Anmerkungen und Bewertungen liegen in diesem Browser. W\xE4hlen Sie einen Ordner auf diesem Computer, dann wird alles auch dort gespeichert, mit einer Kopie von jedem Tag, zu der Sie zur\xFCckkehren k\xF6nnen. Nichts wird hochgeladen.","Sie k\xF6nnen das auch sp\xE4ter in den Einstellungen tun.","Drei kurze Fragen, dann k\xF6nnen Sie korrigieren. Jede Antwort l\xE4sst sich sp\xE4ter \xE4ndern.","Namen sind freiwillig und kommen sp\xE4ter: F\xFCgen Sie auf der Seite der Klasse eine Liste ein oder lassen Sie es weg.","Sie nutzen Grading Studio schon auf einem anderen Computer?","Auf Papier, oder keine Angabe","Ihre Klassen","Ihre Bewertung","Speicherort","Erst mit einer Beispielklasse umsehen","Starten","Schritt {n} von 3","Nur damit die App den Namen verwenden kann. Es wird keine Verbindung hergestellt und nichts gesendet.","Was unterrichten Sie?"],null);export{t as default};
